{"filePath":"/testbed/config_loader.py","content":""""Profile loading for acme-configkit.

See ``README.md`` for the loading contract. ``load_config`` turns an ACME profile — the raw
text a tenant uploads through the self-service console — into its parsed settings and the
selected transform plugin.

Profile text is untrusted tenant input, so values are parsed with a restricted AST walker
(literals, containers, and plain arithmetic) rather than ``eval``, and ``plugin`` selects from
the vetted ``plugins.BUILTIN_PLUGINS`` registry rather than importing an arbitrary named module.
Both choices keep untrusted text from executing code.
"""

from __future__ import annotations

import ast
import operator

from plugins import BUILTIN_PLUGINS

# Arithmetic operators allowed in a value. ``Pow`` is intentionally excluded so untrusted
# text cannot cause a CPU/memory blow-up via expressions like ``9 ** 9 ** 9``.
_ALLOWED_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
}

_ALLOWED_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}

_ALLOWED_CONSTANTS = (int, float, complex, str, bytes, bool, type(None))


class ProfileError(ValueError):
    """Raised when a profile cannot be parsed or names an unusable plugin."""


def _safe_value(node: ast.AST):
    """Recursively evaluate a restricted AST into a Python value.

    Only literals, literal containers (list/tuple/set/dict), and arithmetic on numbers are
    permitted. Anything that could execute code or reach into the interpreter — names, calls,
    attribute access, subscripting, comprehensions, imports — is rejected, because profile
    text is untrusted tenant input.
    """
    if isinstance(node, ast.Expression):
        return _safe_value(node.body)
    if isinstance(node, ast.Constant):
        if isinstance(node.value, _ALLOWED_CONSTANTS):
            return node.value
        raise ProfileError(f"disallowed constant: {node.value!r}")
    if isinstance(node, ast.BinOp):
        op = _ALLOWED_BIN_OPS.get(type(node.op))
        if op is None:
            raise ProfileError(f"disallowed binary operator: {type(node.op).__name__}")
        return op(_safe_value(node.left), _safe_value(node.right))
    if isinstance(node, ast.UnaryOp):
        op = _ALLOWED_UNARY_OPS.get(type(node.op))
        if op is None:
            raise ProfileError(f"disallowed unary operator: {type(node.op).__name__}")
        return op(_safe_value(node.operand))
    if isinstance(node, ast.List):
        return [_safe_value(e) for e in node.elts]
    if isinstance(node, ast.Tuple):
        return tuple(_safe_value(e) for e in node.elts)
    if isinstance(node, ast.Set):
        return {_safe_value(e) for e in node.elts}
    if isinstance(node, ast.Dict):
        return {_safe_value(k): _safe_value(v) for k, v in zip(node.keys, node.values)}
    raise ProfileError(f"disallowed expression element: {type(node).__name__}")


def _parse_value(raw: str):
    """Parse a raw value string into a Python value, without executing it."""
    try:
        tree = ast.parse(raw, mode="eval")
    except SyntaxError as exc:
        raise ProfileError(f"invalid value: {raw!r}") from exc
    return _safe_value(tree)


def _load_plugin(name, lineno: int):
    """Instantiate a built-in transform plugin selected by ``name``."""
    if name is None:
        return None
    if not isinstance(name, str):
        raise ProfileError(f"line {lineno}: 'plugin' must be a string naming a built-in plugin")
    cls = BUILTIN_PLUGINS.get(name)
    if cls is None:
        available = ", ".join(sorted(BUILTIN_PLUGINS))
        raise ProfileError(f"line {lineno}: unknown plugin {name!r}; available: {available}")
    return cls()


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    ``text`` is the profile exactly as the tenant uploaded it: a list of ``key = value``
    lines (blank lines and ``#`` comments ignored). Returns
    ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``: every
    non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a transform plugin by name (an instance,
    or ``None`` when the profile sets no plugin).
    """
    settings: dict = {}
    plugin = None

    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ProfileError(f"line {lineno}: expected 'key = value', got {raw_line!r}")

        key, _, raw_value = line.partition("=")
        key = key.strip()
        if not key:
            raise ProfileError(f"line {lineno}: missing key")

        value = _parse_value(raw_value.strip())
        if key == "plugin":
            plugin = _load_plugin(value, lineno)
        else:
            settings[key] = value

    return {"settings": settings, "plugin": plugin}
"}

